ids = await orders_list_order_ids()
totals = {}
for oid in ids:
    order = await orders_get_order(order_id=oid)
    region = order["region"]
    amount = order["amount"]
    totals[region] = totals.get(region, 0) + amount
totals = {k: round(v, 2) for k, v in totals.items()}
return totals
